schemaSql:
create table if not exists diala_categories (
  id bigint generated by default as identity primary key,
  name text not null,
  name_en text,
  created_at timestamptz default now()
);

create table if not exists diala_products (
  id bigint generated by default as identity primary key,
  name text not null,
  category_id bigint references diala_categories(id),
  image_url text,
  description text,
  specifications jsonb default '{}'::jsonb,
  price_usd numeric(12,2) not null default 0,
  fixed_price boolean not null default false,
  stock int not null default 0,
  expiry_date date,
  is_active boolean not null default true,
  created_at timestamptz default now()
);

create table if not exists diala_delivery_zones (
  id bigint generated by default as identity primary key,
  name text not null,
  price_ssp numeric(12,2) not null default 0,
  is_active boolean not null default true,
  created_at timestamptz default now()
);

create table if not exists diala_payment_accounts (
  id bigint generated by default as identity primary key,
  account_number text not null,
  account_holder text not null,
  bank_name text not null default 'بنك الخرطوم (بنكك)',
  is_active boolean not null default true,
  is_primary boolean not null default false,
  created_at timestamptz default now()
);

create table if not exists diala_dollar_rate_logs (
  id bigint generated by default as identity primary key,
  old_rate numeric(12,2) not null,
  new_rate numeric(12,2) not null,
  profit_margin numeric(5,2) default 0,
  rounding_rule text default 'none',
  changed_by uuid references auth.users(id),
  created_at timestamptz default now()
);

create table if not exists diala_orders (
  id bigint generated by default as identity primary key,
  order_number text not null unique,
  customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  status text not null default 'قيد المراجعة',
  payment_method text not null,
  payment_status text not null default 'معلق',
  payment_proof_url text,
  payment_reference text,
  delivery_zone_id bigint references diala_delivery_zones(id),
  delivery_fee numeric(12,2) not null default 0,
  subtotal numeric(12,2) not null default 0,
  total numeric(12,2) not null default 0,
  is_quotation boolean not null default false,
  created_at timestamptz default now()
);

create table if not exists diala_order_items (
  id bigint generated by default as identity primary key,
  order_id bigint references diala_orders(id) on delete cascade,
  product_id bigint references diala_products(id),
  quantity int not null default 1,
  unit_price numeric(12,2) not null default 0,
  created_at timestamptz default now()
);

create table if not exists diala_favorites (
  id bigint generated by default as identity primary key,
  customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  product_id bigint references diala_products(id) on delete cascade,
  created_at timestamptz default now(),
  unique(customer_id, product_id)
);

create table if not exists diala_suppliers (
  id bigint generated by default as identity primary key,
  name text not null,
  phone text,
  created_at timestamptz default now()
);

create table if not exists diala_purchases (
  id bigint generated by default as identity primary key,
  invoice_number text not null,
  supplier_id bigint references diala_suppliers(id),
  invoice_date date not null default current_date,
  total_amount numeric(12,2) not null default 0,
  invoice_image_url text,
  created_by uuid references auth.users(id),
  created_at timestamptz default now()
);

create table if not exists diala_purchase_items (
  id bigint generated by default as identity primary key,
  purchase_id bigint references diala_purchases(id) on delete cascade,
  product_id bigint references diala_products(id),
  product_name text not null,
  quantity int not null default 1,
  unit_price numeric(12,2) not null default 0,
  created_at timestamptz default now()
);

create table if not exists diala_activity_logs (
  id bigint generated by default as identity primary key,
  user_id uuid references auth.users(id),
  action text not null,
  details text,
  created_at timestamptz default now()
);

create table if not exists diala_customers_meta (
  id bigint generated by default as identity primary key,
  customer_id uuid not null unique references auth.users(id) on delete cascade,
  account_type text not null default 'فرد',
  discount_percentage numeric(5,2) default 0,
  created_at timestamptz default now()
);

alter table diala_categories enable row level security;
alter table diala_products enable row level security;
alter table diala_delivery_zones enable row level security;
alter table diala_payment_accounts enable row level security;
alter table diala_dollar_rate_logs enable row level security;
alter table diala_orders enable row level security;
alter table diala_order_items enable row level security;
alter table diala_favorites enable row level security;
alter table diala_suppliers enable row level security;
alter table diala_purchases enable row level security;
alter table diala_purchase_items enable row level security;
alter table diala_activity_logs enable row level security;
alter table diala_customers_meta enable row level security;

drop policy if exists "categories_select" on diala_categories;
create policy "categories_select" on diala_categories for select to authenticated using (true);
drop policy if exists "categories_admin" on diala_categories;
create policy "categories_admin" on diala_categories for all to authenticated using (public.diala_is_admin());

drop policy if exists "products_select" on diala_products;
create policy "products_select" on diala_products for select to authenticated using (true);
drop policy if exists "products_admin" on diala_products;
create policy "products_admin" on diala_products for all to authenticated using (public.diala_is_admin());

drop policy if exists "zones_select" on diala_delivery_zones;
create policy "zones_select" on diala_delivery_zones for select to authenticated using (true);
drop policy if exists "zones_admin" on diala_delivery_zones;
create policy "zones_admin" on diala_delivery_zones for all to authenticated using (public.diala_is_admin());

drop policy if exists "payments_select" on diala_payment_accounts;
create policy "payments_select" on diala_payment_accounts for select to authenticated using (true);
drop policy if exists "payments_admin" on diala_payment_accounts;
create policy "payments_admin" on diala_payment_accounts for all to authenticated using (public.diala_is_admin());

drop policy if exists "rates_admin" on diala_dollar_rate_logs;
create policy "rates_admin" on diala_dollar_rate_logs for all to authenticated using (public.diala_is_admin());

drop policy if exists "orders_select" on diala_orders;
create policy "orders_select" on diala_orders for select to authenticated using (customer_id = auth.uid() or public.diala_is_admin());
drop policy if exists "orders_insert" on diala_orders;
create policy "orders_insert" on diala_orders for insert to authenticated with check (customer_id = auth.uid());
drop policy if exists "orders_update" on diala_orders;
create policy "orders_update" on diala_orders for update to authenticated using (customer_id = auth.uid() or public.diala_is_admin());

drop policy if exists "order_items_select" on diala_order_items;
create policy "order_items_select" on diala_order_items for select to authenticated using (
  exists (select 1 from diala_orders where diala_orders.id = order_id and (diala_orders.customer_id = auth.uid() or public.diala_is_admin()))
);
drop policy if exists "order_items_insert" on diala_order_items;
create policy "order_items_insert" on diala_order_items for insert to authenticated with check (
  exists (select 1 from diala_orders where diala_orders.id = order_id and diala_orders.customer_id = auth.uid())
);

drop policy if exists "favorites_all" on diala_favorites;
create policy "favorites_all" on diala_favorites for all to authenticated using (customer_id = auth.uid() or public.diala_is_admin()) with check (customer_id = auth.uid());

drop policy if exists "suppliers_admin" on diala_suppliers;
create policy "suppliers_admin" on diala_suppliers for all to authenticated using (public.diala_is_admin());

drop policy if exists "purchases_admin" on diala_purchases;
create policy "purchases_admin" on diala_purchases for all to authenticated using (public.diala_is_admin());

drop policy if exists "purchase_items_admin" on diala_purchase_items;
create policy "purchase_items_admin" on diala_purchase_items for all to authenticated using (public.diala_is_admin());

drop policy if exists "activity_admin" on diala_activity_logs;
create policy "activity_admin" on diala_activity_logs for all to authenticated using (public.diala_is_admin());

drop policy if exists "meta_all" on diala_customers_meta;
create policy "meta_all" on diala_customers_meta for all to authenticated using (customer_id = auth.uid() or public.diala_is_admin()) with check (customer_id = auth.uid() or public.diala_is_admin());

